import{_ as o,y as n,a,o as i,a2 as e,D as s}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Email Settings","description":"","frontmatter":{},"headers":[],"relativePath":"configure/email-settings.md","filePath":"configure/email-settings.md","lastUpdated":1789441803000}'),d={name:"configure/email-settings.md"};function l(g,t,h,m,c,u){const r=n("ImagePopup");return i(),a("div",null,[t[0]||(t[0]=e('<h1 id="email-settings" tabindex="-1">Email Settings <a class="header-anchor" href="#email-settings" aria-label="Permalink to &quot;Email Settings&quot;">​</a></h1><p>The <strong>Email Settings</strong> screen decides how your store sends email, and the names and addresses emails are sent from.</p><h2 id="mail-driver" tabindex="-1">Mail driver <a class="header-anchor" href="#mail-driver" aria-label="Permalink to &quot;Mail driver&quot;">​</a></h2><p>The mail driver applies to the whole store.</p><ol><li>Go to <strong>Configure &gt;&gt; Email &gt;&gt; Email Settings</strong>.</li><li>In <strong>Mail Driver</strong>, choose the <strong>Driver</strong>: <strong>SMTP</strong> (the default) or <strong>Brevo (API)</strong>. Only the fields of that driver are shown.</li><li>For <strong>SMTP</strong>, enter the settings described in the table.</li><li>For <strong>Brevo (API)</strong>, enter your <strong>Brevo API Key</strong>.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',5)),s(r,{src:"/images/configure/email-mail-driver.png",alt:"Mail Driver section of the Email Settings screen with the SMTP fields"}),t[1]||(t[1]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Driver</strong></td><td>How email is sent: <strong>SMTP</strong> sends it through a mail server, such as the one your email provider gives you, and <strong>Brevo (API)</strong> sends it through Brevo&#39;s web service.</td></tr><tr><td><strong>Brevo API Key</strong></td><td>Appears for <strong>Brevo (API)</strong>. Create a v3 API key in your Brevo account under <strong>SMTP &amp; API</strong>.</td></tr><tr><td><strong>Host</strong></td><td>Appears for <strong>SMTP</strong>, like the settings below it. The address of your mail server. Required.</td></tr><tr><td><strong>Port</strong></td><td>The port of your mail server, such as <code>587</code>. Required.</td></tr><tr><td><strong>Encryption</strong></td><td><strong>TLS</strong>, <strong>SSL</strong> or <strong>None</strong>. Use the one your email provider tells you to.</td></tr><tr><td><strong>Username</strong></td><td>The account the store signs in to the mail server with.</td></tr><tr><td><strong>Password</strong></td><td>The password of that account.</td></tr></tbody></table><p>The SMTP settings start with the values from the server&#39;s environment file, so they may already be filled in. The <strong>Mail</strong> card on the <a href="./about.html">About</a> screen shows which driver is in use.</p><h3 id="these-settings-are-currently-inactive" tabindex="-1">These settings are currently inactive <a class="header-anchor" href="#these-settings-are-currently-inactive" aria-label="Permalink to &quot;These settings are currently inactive&quot;">​</a></h3><p>If the section shows <em>These settings are currently inactive.</em>, your server is set to send email another way and changes here have no effect. Ask whoever manages your server to set the store&#39;s mailer to <code>bagisto-dynamic-smtp</code> in its environment file.</p><h2 id="email-settings-1" tabindex="-1">Email settings <a class="header-anchor" href="#email-settings-1" aria-label="Permalink to &quot;Email settings&quot;">​</a></h2><p>The sender details are saved per channel, so choose the channel at the top of the screen first when your store has more than one.</p><ol><li>Go to <strong>Configure &gt;&gt; Email &gt;&gt; Email Settings</strong>.</li><li>In <strong>Email Settings</strong>, enter the six details described in the table.</li><li>Click <strong>Save Configuration</strong>.</li></ol>',7)),s(r,{src:"/images/configure/email-sender-details.png",alt:"Email Settings section with the sender, admin and contact details"}),t[2]||(t[2]=e('<table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Sender Name</strong></td><td>The name customers see as the sender of your emails. Up to 50 characters.</td></tr><tr><td><strong>Sender Email Address</strong></td><td>The address emails to customers are sent from.</td></tr><tr><td><strong>Admin Name</strong></td><td>The name used in emails sent to the admin. Up to 50 characters.</td></tr><tr><td><strong>Admin Email Address</strong></td><td>The address admin notifications for the channel are sent to.</td></tr><tr><td><strong>Contact Name</strong></td><td>The name that goes with your contact email address. Up to 50 characters.</td></tr><tr><td><strong>Contact Email Address</strong></td><td>The address shown in the footer of your emails.</td></tr></tbody></table><p>All six are required, and they start with the values from the server&#39;s environment file. Which emails are sent is set under <a href="./notifications.html">Notifications</a>. These details are also used by the emails described in <a href="./../customer/gdpr-data-requests.html">GDPR Data Requests</a> and <a href="./../orders/eu-withdrawal.html">EU Withdrawal</a>.</p><h2 id="differences-in-bagisto-2-4" tabindex="-1">Differences in Bagisto 2.4 <a class="header-anchor" href="#differences-in-bagisto-2-4" aria-label="Permalink to &quot;Differences in Bagisto 2.4&quot;">​</a></h2><p>The <strong>Driver</strong> and <strong>Brevo API Key</strong> settings are available from Bagisto 2.4.10. Earlier 2.4 releases send email only through SMTP, with the <strong>Host</strong>, <strong>Port</strong>, <strong>Encryption</strong>, <strong>Username</strong> and <strong>Password</strong> settings.</p>',4))])}const v=o(d,[["render",l]]);export{p as __pageData,v as default};
